# frozen_string_literal: true
class Types::FormResponseChangeType < Types::BaseObject
  description "A recorded change to one field of a form response"
  # no ID field because these can be autogenerated by CompactingFormResponseChangesPresenter

  field :compacted,
        Boolean,
        null: false,
        description: "Whether this change has been through compaction, which merges nearby edits"
  field :created_at, Types::DateType, null: false, description: "When this change was made"
  field :field_identifier, String, null: false, description: "The identifier of the form item that changed"
  field :new_value, Types::JSON, null: true, description: "The value after the change"
  field :notified_at,
        Types::DateType,
        null: true,
        description: "When notifications about this change were sent, if they have been"
  field :previous_value, Types::JSON, null: true, description: "The value before the change"
  field :updated_at, Types::DateType, null: false, description: "When this change record was last updated"
  field :user_con_profile, Types::UserConProfileType, null: false, description: "The person who made the change"

  association_loaders FormResponseChange, :user_con_profile
end
